import{z as i,x as l,o as B,c as p,q as r,j as A,D as E,d as s,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"USB 协议分层","description":"","frontmatter":{"title":"USB 协议分层","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/usb-protocol.md","filePath":"cs/usb-protocol.md","lastUpdated":1791413859000}'),D={name:"cs/usb-protocol.md"};function S(d,a,C,m,P,c){const t=l("Mermaid");return B(),p("div",null,[a[2]||(a[2]=r('<h1 id="usb-协议分层" tabindex="-1">USB 协议分层 <a class="header-anchor" href="#usb-协议分层" aria-label="Permalink to &quot;USB 协议分层&quot;">​</a></h1><div class="epigraph"><p>USB 把设备、配置、接口、端点叠成树，传输分控制/批量/中断/等时；主机控制器用描述符 DMA 调度微帧，而不是 CPU 比特翻转 D+/D−。</p><footer>—— 据 USB Implementers Forum, USB Specification；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/dma-scatter-gather">上一课</a>给出通用 DMA。<a href="/cs/pcie-lanes">PCIe</a> 上的 xHCI 是主机控制器端点。缺口是 <strong>USB 分层</strong>：与 PCIe TLP 不同的包与端点模型，让键盘、盘、网共用一条树形总线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>USB：主机为根的树，集线器分层。设备描述符→配置→接口→端点。传输类型：控制（枚举）、批量（盘）、中断（HID 轮询间隔）、等时（音频，允许丢）。缺口不是再讲 SG 表，而是 xHCI Transfer Ring 上的 TRB 如何对应这些传输。物理层随代变（LS/FS/HS/SS），本课不画眼图。</p><p>枚举：复位、取描述符、设地址、配配置——固件/OS 早期就会做，与后课 BIOS 枚举 PCI 并列。</p><h3 id="usb-不是「小版-pcie」" tabindex="-1">USB 不是「小版 PCIe」 <a class="header-anchor" href="#usb-不是「小版-pcie」" aria-label="Permalink to &quot;USB 不是「小版 PCIe」&quot;">​</a></h3><p>USB 是主机轮询/调度的共享树（尽管 SS 有更多点对点味道），设备不主动发任意 Memory TLP 到全系统（USB4/雷电另议）。把优盘当 PCIe NVMe 端点，BAR 模型会套错。对主机而言优盘是 SCSI/UAS 命令再进批量端点。</p><p><span class="marginnote">USB 规范是分层权威。Patterson/Hennessy 把 USB 当 I/O 例子。xHCI 规范描述环与 DMA。本课钉层次与传输类，不背描述符每个字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件：URB/请求块 → 主机控制器驱动填 TRB → DMA → 端口收发包。盘：Bulk + BOT 或 UAS。HID：中断入端点。与 <a href="/cs/msi-msix">MSI</a>：xHCI 用 MSI-X 通知环事件。电源：挂起与远程唤醒点名。</p>',11)),(B(),A(n,null,{default:E(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TREE%5B%22%E4%B8%BB%E6%9C%BA-%E9%9B%86%E7%BA%BF%E5%99%A8-%E8%AE%BE%E5%A4%87%E6%A0%91%22%5D%20--%3E%20EP%5B%22%E7%AB%AF%E7%82%B9%22%5D%0A%20%20EP%20--%3E%20XFER%5B%22%E6%8E%A7%E5%88%B6%2F%E6%89%B9%E9%87%8F%2F%E4%B8%AD%E6%96%AD%2F%E7%AD%89%E6%97%B6%22%5D%0A%20%20XFER%20--%3E%20xHCI%5B%22xHCI%20DMA%20%E7%8E%AF%22%5D%0A%20%20xHCI%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9B%B4%E7%AE%80%E5%8D%95%E7%9A%84%E7%89%87%E4%B8%8A%E4%B8%B2%E5%8F%A3%E6%80%BB%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"对比 I²C/SPI：那些是片内短线，无 USB 描述符树。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"一根 U 盘插上端口后到能被访问，主机走完的枚举流程如下：",-1)),(B(),A(n,null,{default:E(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLUG%5B%22%E8%AE%BE%E5%A4%87%E6%8F%92%E5%85%A5%2C%20VBUS%20%E4%B8%8A%E7%94%B5%22%5D%20--%3E%20RST%5B%22%E4%B8%BB%E6%9C%BA%E5%8F%91%E6%80%BB%E7%BA%BF%E5%A4%8D%E4%BD%8D%22%5D%0A%20%20RST%20--%3E%20DEF%5B%22%E8%AE%BE%E5%A4%87%E4%BB%A5%E5%9C%B0%E5%9D%80%200%20%E5%BA%94%E7%AD%94%22%5D%0A%20%20DEF%20--%3E%20GD%5B%22GET_DESCRIPTOR%20%E8%AF%BB%E8%AE%BE%E5%A4%87%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20GD%20--%3E%20SA%5B%22SET_ADDRESS%20%E5%88%86%E9%85%8D%E5%9C%B0%E5%9D%80%20(%E5%A6%82%207)%22%5D%0A%20%20SA%20--%3E%20CFG%5B%22%E5%86%8D%E5%8F%96%E9%85%8D%E7%BD%AE%2F%E6%8E%A5%E5%8F%A3%2F%E7%AB%AF%E7%82%B9%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20CFG%20--%3E%20SCC%5B%22SET_CONFIGURATION%20%E9%80%89%E5%AE%9A%E9%85%8D%E7%BD%AE%22%5D%0A%20%20SCC%20--%3E%20DRV%5B%22%E5%8A%A0%E8%BD%BD%E5%8C%B9%E9%85%8D%E7%9A%84%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20DRV%20--%3E%20READY%5B%22%E7%AB%AF%E7%82%B9%E5%B0%B1%E7%BB%AA%2C%20%E5%8F%AF%E6%89%B9%E9%87%8F%E4%BC%A0%E8%BE%93%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>下一课片上低速总线给传感器与闪存颗粒旁路。显示链路（eDP）不是 USB，帧缓冲课再接。本课把「外设树」从 PCIe 交换机树区分开：PCIe 枚举配置空间；USB 枚举描述符。</p><p><span class="marginnote">端点可以翻译成「设备内部的收发信箱」：一个端点号加方向（IN 指向主机、OUT 离开主机）定位一个缓冲区。键盘占用一对中断端点，U 盘占一对批量端点——描述符树列的就是这些信箱的地址与作息表。</span></p><p><span class="marginnote">数字实例：高速（HS）模式微帧长 \\(125\\ \\mu s\\)，键盘的中断端点常被配成每微帧轮询一次，即每秒最多 8000 次「有键吗」。这解释了为什么键盘不用批量传输——批量没有轮询保障，按键会等到来回攒够一批才被问一次。</span></p><p><span class="marginnote">常见误区：以为插上 U 盘后设备会「主动报到」。USB 是主机调度的总线，设备永远只应答、不发起——没有主机轮询它就是哑的。这与 PCIe 设备可主动发 TLP 的模型正相反，也是本课反复强调「不是小版 PCIe」的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 USB4 隧道 PCIe 的全部，不把 Type-C PD 电源合同当主体。不讨论驱动签名。不进入音频等时抖动的信号处理。</p><p>后课默认：USB 是主机调度的端点传输；xHCI 用 DMA 环；与 PCIe 端点模型不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设备树 + 四类传输；控制通路做枚举。</li><li>xHCI 把传输变成 DMA 描述符。</li><li>不是 PCIe Memory TLP 的缩微。</li><li>出处：USB Specification；xHCI；Patterson and Hennessy, COD。</li></ul>',9))])}const u=i(D,[["render",S]]);export{F as __pageData,u as default};
